83	        assertEquals(200, checkedOut.statusCode());
84	        assertEquals("Comprovante de reserva", json.readTree(checkedOut.body()).get("title").asText());
85	        assertEquals("CHECKED_OUT", json.readTree(get("/reservations/" + id).body()).get("status").asText());
86	    }
